// Combine all 8 categories
const allServices = [];

function processList(list, catName, prefix) {
  list.forEach((item, idx) => {
    const num = String(idx + 1).padStart(3, '0');
    const codeNum = String(idx + 1).padStart(2, '0');
    allServices.push({
      id: `${prefix}-${num}`,
      code: `NST-${prefix.toUpperCase()}${codeNum}`,
      title: item[0],
      category: catName,
      subCategory: item[1],
      reraStandard: item[2],
      description: item[3],
      deliverables: item[4],
      timeframe: item[5],
      pricing: { aed: item[6], billingType: item[7], label: item[8] },
      propertyType: item[9],
      popular: item[10] || false
    });
  });
}

