processList(legal, 'RERA & Legal Compliance', 'leg');
processList(maintenance, 'Preventive Maintenance & AMC', 'amc');
processList(leasing, 'Tenant Lifecycle & Leasing', 'ten');
processList(holiday, 'Holiday Home & Short-Term', 'hol');
